from pathlib import Path
p=Path('/mnt/data/gcbtp_work/v3work/shared/reinforcement-report.ts')
s=p.read_text()
insert='''\nexport type ReinforcementA4Group = {\n  key: string;\n  type: RCElementDesign["type"];\n  elements: RCElementDesign[];\n  representative: RCElementDesign;\n  identicalReinforcement: boolean;\n};\n\nfunction reinforcementFingerprint(element: RCElementDesign) {\n  return element.reinforcement\n    .map(bar => [bar.id.split(":").slice(-1)[0], bar.label, bar.diameterMm, bar.count, Math.round(bar.lengthPerBarM * 1000)].join("|"))\n    .sort()\n    .join(";");\n}\n\nexport function reinforcementGroupingKey(element: RCElementDesign, geometryLabel = "") {\n  // Le regroupement principal est volontairement basé sur le type + section/géométrie.\n  // Le ferraillage est comparé ensuite afin de distinguer les variantes sans créer un PDF par élément.\n  const section = geometryLabel\n    .replace(/\\s+/g, " ")\n    .replace(/longueur [^·]+/i, "")\n    .trim()\n    .toLowerCase();\n  return `${element.type}::${section || "section-non-renseignee"}`;\n}\n\nexport function groupReinforcementElements(elements: RCElementDesign[], geometryById: Record<string, string> = {}) {\n  const map = new Map<string, RCElementDesign[]>();\n  for (const element of elements) {\n    const key = reinforcementGroupingKey(element, geometryById[element.elementId]);\n    const list = map.get(key) ?? [];\n    list.push(element);\n    map.set(key, list);\n  }\n  return Array.from(map.entries()).map(([key, group]) => {\n    const fingerprint = reinforcementFingerprint(group[0]);\n    return {\n      key,\n      type: group[0].type,\n      elements: group,\n      representative: group[0],\n      identicalReinforcement: group.every(item => reinforcementFingerprint(item) === fingerprint),\n    } satisfies ReinforcementA4Group;\n  });\n}\n'''
needle='export function reinforcementElementSummary(element: RCElementDesign) {'
pos=s.index(needle)
s=s[:pos]+insert+'\n'+s[pos:]
p.write_text(s)
